import os,glob,re,sys,collections
try:
    import yaml
except ImportError:
    yaml=None
def fm(p):
    t=open(p,encoding='utf-8',errors='replace').read()
    if not t.startswith('---'): return None,'nofm'
    m=re.match(r'^---\r?\n(.*?)\r?\n---',t,re.S)
    if not m: return None,'unterminated'
    if yaml:
        try: d=yaml.safe_load(m.group(1)); return (d if isinstance(d,dict) else {}),None
        except Exception as e: return None,'yaml: '+str(e).splitlines()[0]
    return {},None
print("yaml lib:",bool(yaml))
for base in [os.path.expanduser('~/DEV/.claude/agents'),os.path.expanduser('~/.claude/agents')]:
    names=collections.defaultdict(list)
    for p in glob.glob(base+'/**/*.md',recursive=True):
        d,e=fm(p)
        if e: print("AGENT-ERR",p,e); continue
        if d and d.get('name'):
            if not d.get('description'): print("AGENT-NODESC",p)
            names[(os.path.dirname(p),d['name'])].append(p)
    for k,v in names.items():
        if len(v)>1: print("AGENT-COLLIDE",k,v)
    print("agents scanned",base,sum(len(v) for v in names.values()))
n=0
for base in [os.path.expanduser('~/DEV/.claude/skills'),os.path.expanduser('~/.claude/skills')]:
    for p in glob.glob(base+'/*/SKILL.md'):
        n+=1
        d,e=fm(p)
        if e: print("SKILL-ERR",p,e)
print("skills scanned",n)
