cat > $CLAUDE_JOB_DIR/tmp/scan.py <<'PY'
import json,glob,os,re,collections,time,statistics
H=os.path.expanduser('~')
files=sorted(glob.glob(H+'/.claude/projects/*/*.jsonl'),key=os.path.getmtime,reverse=True)[:50]
oldest=os.path.getmtime(files[-1]); win_start=oldest
print("window: %d sessions, %.1f days"%(len(files),(time.time()-oldest)/86400))
skill=collections.Counter(); slash=collections.Counter(); mcp=collections.Counter()
hooks=collections.defaultdict(list); timeouts=collections.Counter()
uses={}; denials=collections.Counter(); dk=collections.defaultdict(collections.Counter)
for f in files:
    pend={}
    for line in open(f,errors='replace'):
        try: o=json.loads(line)
        except: continue
        t=o.get('type')
        if t=='assistant':
            for c in (o.get('message') or {}).get('content') or []:
                if isinstance(c,dict) and c.get('type')=='tool_use':
                    n=c.get('name','')
                    uses[c.get('id')]=(n,c.get('input') or {})
                    if n=='Skill': skill[str((c.get('input') or {}).get('skill'))]+=1
                    if n.startswith('mcp__'): mcp[n.split('__')[1]]+=1
        elif t=='user':
            m=o.get('message') or {}
            cont=m.get('content')
            s=cont if isinstance(cont,str) else json.dumps(cont)
            for x in re.findall(r'<command-name>/?([^<]+)</command-name>',s): slash[x]+=1
            k=o.get('toolDenialKind')
            if k and k not in('interrupted','cancelled') and isinstance(cont,list):
                for c in cont:
                    if isinstance(c,dict) and c.get('type')=='tool_result':
                        n,inp=uses.get(c.get('tool_use_id'),('?',{}))
                        if n=='Bash':
                            cmd=str(inp.get('command','')).strip().split()
                            key='Bash: '+' '.join(cmd[:2])
                        else: key=n
                        denials[key]+=1; dk[key][k]+=1
        elif t=='attachment':
            a=o.get('attachment') or {}
            if str(a.get('type','')).startswith('hook_'):
                key=(a.get('hookEvent'),os.path.basename(str(a.get('command',a.get('hookName','')))[:80]))
                if a.get('durationMs') is not None: hooks[key].append(a['durationMs'])
                if a.get('timedOut'): timeouts[key]+=1
print("SKILL tool:",dict(skill.most_common()))
print("SLASH:",dict(slash.most_common()))
print("MCP servers:",dict(mcp.most_common()))
print("HOOKS (event, cmd, n, median ms, max ms):")
for k,v in sorted(hooks.items(),key=lambda kv:-statistics.median(kv[1])):
    print(" ",k,len(v),int(statistics.median(v)),max(v),"timeouts=%d"%timeouts[k])
print("DENIALS:")
for k,n in denials.most_common(15): print(" ",n,k,dict(dk[k]))
json.dump({'win_start':win_start},open(os.environ['CLAUDE_JOB_DIR']+'/tmp/win.json','w'))
